const body = $input.first().json.body || $input.first().json;
const norm = (ph) => {
  if (!ph) return null;
  let p = String(ph).replace(/\D/g, '');
  if (p.startsWith('20')) return p;
  if (p.length === 10) return '20' + p;
  if (p.length === 11 && p.startsWith('0')) return '20' + p.slice(1);
  return p;
};
let event_type = body.event_type || null;
let phone = null;
if (!event_type) {
  const hasTally = !!(body.data && body.data.fields) || !!(body.fields);
  const hasWA = !!(body.data && body.data.key);
  const hasBooking = !!(body.patient_phone && body.appointment_date);
  if (hasTally) event_type = 'tally_form_submission';
  else if (hasWA) event_type = 'inbound_whatsapp';
  else if (hasBooking) event_type = 'new_booking';
  else event_type = 'fallback_unknown';
}
if (event_type === 'new_booking') phone = norm(body.patient_phone);
else if (event_type === 'inbound_whatsapp') {
  const key = (body.data && body.data.key) || {};
  phone = norm((key.remoteJid || '').replace('@s.whatsapp.net', '').replace('@g.us', ''));
} else if (event_type === 'tally_form_submission') {
  const fields = (body.data && body.data.fields) || body.fields || [];
  const pf = fields.find(f => f.label && f.label.toLowerCase().includes('phone'));
  if (pf) phone = norm(String(pf.value || '').replace(/\D/g, ''));
}
return [{ json: { event_type, source: 'webhook', timestamp: new Date().toISOString(), phone, payload: body } }];

const d = $json;
const p = d.payload || d;
const norm = (ph) => {
  if (!ph) return null;
  let s = String(ph).replace(/\D/g, '');
  if (s.startsWith('20')) return s;
  if (s.length === 10) return '20' + s;
  if (s.length === 11 && s.startsWith('0')) return '20' + s.slice(1);
  return s;
};
const phone = norm(p.patient_phone || d.phone);
if (!phone || phone.length < 10) return [{ json: { skip: true, reason: 'invalid_phone' } }];
const hour = parseInt(new Date().toLocaleString('en-US', { timeZone: 'Africa/Cairo', hour: 'numeric', hour12: false }));
if (hour >= 23 || hour < 8) return [{ json: { skip: true, reason: 'outside_hours' } }];
const patientName = (p.patient_name || 'مريض').trim();
const doctorName = (p.doctor_name || 'الدكتور').trim();
const appointmentDate = p.appointment_date || '';
const appointmentTime = p.appointment_time || '';
const tallyUrl = p.tally_form_url || '{{ $env.INTAKE_FORM_URL }}';
const message = 'أهلاً ' + patientName + '! 😊\n\n✅ تم تأكيد موعدك مع ' + doctorName + '\n📅 ' + appointmentDate + ' الساعة ' + appointmentTime + '\n\nعشان نوفر وقتك ونقدملك أحسن خدمة، ممكن تملي بياناتك الطبية قبل ما تيجي؟\n\n📋 الاستمارة هنا (3 دقايق):\n' + tallyUrl + '\n\nدا هيخلي الدكتور مستعد ليك تماماً 🙏';
return [{ json: { phone, patientName, doctorName, appointmentDate, appointmentTime, tallyUrl, message, skip: false, safeName: patientName.replace(/'/g, "''"), safeDr: doctorName.replace(/'/g, "''") } }];

const ext = $('A — Extract Booking').first().json;
const pg = $input.first().json || {};
return [{ json: { ...ext, existing_id: pg.existing_id || null, form_submitted: pg.form_submitted === true } }];

const d = $json;
const body = d.payload || d;
const fields = (body.data && body.data.fields) ? body.data.fields : (body.fields ? body.fields : []);
const responseId = (body.data && body.data.responseId) ? body.data.responseId : 'unknown';
const getVal = (label) => {
  const f = fields.find(f => f.label && f.label.toLowerCase() === label.toLowerCase());
  if (!f || f.value === null || f.value === undefined) return '';
  if (Array.isArray(f.value)) return f.value.join(', ');
  return String(f.value).trim();
};
const rawPhone = getVal('Phone Number').replace(/\D/g, '');
const phone = rawPhone.startsWith('20') ? rawPhone : '20' + rawPhone;
const patientName = getVal('Full Name') || 'مريض';
const dob = getVal('Date of Birth');
const gender = getVal('Gender');
const chiefComplaint = getVal('Chief Complaint');
const allergies = getVal('Known Allergies') || 'لا يوجد';
const medications = getVal('Current Medications') || 'لا يوجد';
const conditions = getVal('Chronic Conditions') || 'لا يوجد';
const dentalConcerns = getVal('Dental Concerns');
const lastVisit = getVal('Last Dental Visit');
const surgeries = getVal('Previous Dental Surgeries') || 'لا يوجد';
const insurance = getVal('Insurance Provider') || 'Self-pay';
const emergName = getVal('Emergency Contact Name');
const emergPhone = getVal('Emergency Contact Phone');
const xrayConsent = getVal('X-Ray Consent') === 'Yes';
const doctorName = getVal('Doctor Name') || 'الدكتور';
if (!phone || phone.length < 10) return [{ json: { error: true, reason: 'missing_phone', phone: '', patientName: 'مريض', responseId } }];
if (!chiefComplaint) return [{ json: { error: true, reason: 'missing_complaint', phone, patientName, responseId } }];
const safe = (s) => String(s || '').replace(/'/g, "''");
return [{ json: { phone, patientName, dob, gender, chiefComplaint, allergies, medications, conditions, dentalConcerns, lastVisit, surgeries, insurance, emergName, emergPhone, xrayConsent, doctorName, responseId, error: false, safePhone: safe(phone), safeName: safe(patientName), safeDob: safe(dob), safeGender: safe(gender), safeComplaint: safe(chiefComplaint), safeAllergies: safe(allergies), safeMeds: safe(medications), safeConditions: safe(conditions), safeDentalConcerns: safe(dentalConcerns), safeLastVisit: safe(lastVisit), safeSurgeries: safe(surgeries), safeInsurance: safe(insurance), safeEmergName: safe(emergName), safeEmergPhone: safe(emergPhone), safeDr: safe(doctorName) } }];

const extracted = $('B — Extract Tally Fields').first().json;
const pg = $input.first().json || {};
return [{ json: { ...extracted, duplicate_id: pg.duplicate_id || null, is_duplicate: !!(pg.duplicate_id) } }];

const groqRaw = $input.first().json;
const intakeData = $('B — Extract Tally Fields').first().json;
let analysis = {};
try { analysis = JSON.parse(groqRaw.choices[0].message.content); } catch(e) {
  analysis = { risk_level: 'low', risk_score: 20, red_flags: [], staff_note_ar: 'مريض روتيني — لا ملاحظات خاصة', staff_note_en: 'Routine patient', latex_free_needed: false, antibiotic_prophylaxis_needed: false, xray_approved: intakeData.xrayConsent, patient_message_ar: 'شكراً ' + intakeData.patientName + '! ✅ استلمنا بياناتك. نتطلع نشوفك! 😊', prep_instructions_ar: 'يرجى تفريش أسنانك جيداً قبل الزيارة.', recommended_priority: 'routine' };
}
const safe = (s) => String(s || '').replace(/'/g, "''");
const redFlagsStr = Array.isArray(analysis.red_flags) ? analysis.red_flags.join(', ') : (analysis.red_flags || '');
return [{ json: { ...intakeData, riskLevel: analysis.risk_level || 'low', riskScore: analysis.risk_score || 0, redFlags: redFlagsStr, staffNoteAr: analysis.staff_note_ar || '', staffNoteEn: analysis.staff_note_en || '', latexFree: analysis.latex_free_needed || false, antibioticNeeded: analysis.antibiotic_prophylaxis_needed || false, xrayApproved: analysis.xray_approved || false, patientMessageAr: analysis.patient_message_ar || '', prepInstructions: analysis.prep_instructions_ar || '', priority: analysis.recommended_priority || 'routine', safeStaffNote: safe(analysis.staff_note_ar || ''), safeRedFlags: safe(redFlagsStr), safePrep: safe(analysis.prep_instructions_ar || '') } }];

const d = $json;
const body = d.payload || d;
const data = body.data || {};
const key = data.key || {};
const msgObj = data.message || {};
const phone = d.phone || (key.remoteJid || '').replace('@s.whatsapp.net', '').replace('@g.us', '');
const rawMsg = msgObj.conversation || (msgObj.extendedTextMessage && msgObj.extendedTextMessage.text) || (msgObj.imageMessage && msgObj.imageMessage.caption) || (msgObj.buttonsResponseMessage && msgObj.buttonsResponseMessage.selectedDisplayText) || (msgObj.listResponseMessage && msgObj.listResponseMessage.title) || '';
const fromMe = key.fromMe === true;
const pushName = data.pushName || '';
const INSTANCE_MAP = { '{{ EVOLUTION_INSTANCE }}': 'clinic_001', 'whatsapp-bot': 'clinic_001' };
const instanceName = body.instance || body.instanceName || '{{ EVOLUTION_INSTANCE }}';
const clinic_id = INSTANCE_MAP[instanceName] || 'clinic_001';
if (fromMe || !rawMsg) return [];
return [{ json: { phone, message: rawMsg, pushName, fromMe: false, clinic_id, instanceName } }];

const ext = $('C — Extract WA Message').first().json;
const historyItems = $input.all();
const phone = ext.phone;
const message = ext.message;
const pushName = ext.pushName;
const clinic_id = ext.clinic_id || 'clinic_001';
const allMessages = historyItems.map(item => item.json).filter(m => m && m.message_text);
let history = allMessages.slice().reverse().map(m => ({ role: m.direction === 'inbound' ? 'user' : 'model', parts: [{ text: m.message_text || '' }] }));
while (history.length > 0 && history[history.length - 1].role === 'model') history.pop();
const sys = 'You are a warm, empathetic AI assistant for a dental clinic. Multilingual: Arabic, English, Arabizi, French. Never robotic.\nPatient: ' + (pushName || 'Patient') + '\n\nRULES:\n- Match patient language exactly\n- Anxiety: validate feelings, then reassure about painless modern dentistry\n- Price questions: doctor estimates after exam; never quote prices\n- Complaints: empathy first, set escalate=true\n- Compliment after first reply: set send_review_link=true\n- Opt-out request: set next_action=close_session\n\nReturn ONLY valid JSON with these fields: reply_message (string), sentiment (positive/negative/neutral), sentiment_score (float 0-1), intent (booking/reschedule/pain/price_inquiry/complaint/review/anxiety/form_help/compliment/opt_out/other), escalate (boolean), escalate_reason (string), send_review_link (boolean), detected_language (arabic/english/arabizi/french/mixed), confidence (float 0-1), next_action (wait_reply/escalate/close_session/send_form_link).';
const contents = [...history, { role: 'user', parts: [{ text: message }] }];
const geminiPayload = { system_instruction: { parts: [{ text: sys }] }, contents, generationConfig: { responseMimeType: 'application/json', temperature: 0.4, maxOutputTokens: 1024 } };
const sid = phone + '_' + new Date().toISOString().split('T')[0];
return [{ json: { phone, message, pushName, clinic_id, sessionId: sid, geminiPayload } }];

const prev = $('C — Build Groq Chat Payload').first().json;
const gr = $input.first().json;
let ai = {};
try {
  const text = gr.candidates[0].content.parts[0].text;
  ai = typeof text === 'string' ? JSON.parse(text) : text;
} catch(e) {
  ai = { reply_message: 'نرد عليك خلال دقايق، شكراً لصبرك 🙏', sentiment: 'neutral', sentiment_score: 0.5, intent: 'other', confidence: 0.3, escalate: false, escalate_reason: '', send_review_link: false, detected_language: 'arabic', next_action: 'wait_reply' };
}
return [{ json: { ...prev, ...ai, phone: prev.phone, message: prev.message, clinic_id: prev.clinic_id, sessionId: prev.sessionId } }];

const d = $input.first().json;
const prep = d.prep_instructions || 'يرجى تفريش أسنانك جيداً قبل الزيارة وإحضار أي أشعة أو تقارير سابقة.';
const message = 'أهلاً ' + d.patient_name + '! 👋

تذكير بموعدك بكرة مع ' + d.doctor_name + '
الساعة ' + d.appointment_time + ' ⏰

' + prep + '

نتطلع نشوفك! 😊';
return [{ json: { ...d, reminderMessage: message } }];

const d = $input.first().json;
const message = 'أهلاً ' + d.patient_name + '! 👋

موعدك بكرة مع ' + d.doctor_name + ' ⏰

لسه ما ملأتش الاستمارة الطبية — دي هتوفرلك وقت كتير في العيادة:
📋 {{ $env.INTAKE_FORM_URL }}

لو عندك أي سؤال كلمنا هنا 💙';
return [{ json: { ...d, reminderMessage: message } }];

return $input.all()
  .filter(item => item.json && item.json.phone)
  .map(item => {
  const p = item.json;
  const name = p.full_name || 'مريض';
  const doctor = p.doctor_name || 'الدكتور';
  const message = 'أهلاً ' + name + ' 😊\n\nنتمنى إن زيارتك النهاردة لـ ' + doctor + ' كانت مريحة.\n\nإيه رأيك في التجربة؟ صراحتك بتساعدنا نتحسن ليك وللناس التانية 🙏';
  return { json: { ...p, message, safeName: name.replace(/'/g, "''"), safeDr: doctor.replace(/'/g, "''"), safePhone: (p.phone||'').replace(/'/g, "''"), safeClinic: (p.clinic_name||'العيادة').replace(/'/g, "''"), safeGLink: (p.google_maps_link||'').replace(/'/g, "''"), safeMgr: (p.manager_phone||'20XXXXXXXXXX').replace(/'/g, "''") } };
});

return $input.all()
  .filter(item => item.json && item.json.patient_phone)
  .map(item => {
  const p = item.json;
  const sysMsg = 'You are a clinic care assistant. Write a SHORT warm Arabic follow-up care message (max 100 words) for a patient who had ' + (p.visit_type || 'general') + ' care 5-7 days ago. Include specific care tips. Patient: ' + (p.patient_name || 'Patient') + ', Doctor: ' + (p.doctor_name || 'Doctor') + '. End with invitation to rebook at ' + (p.manager_phone || '+20XXXXXXXXXX') + '. Return ONLY the Arabic message text.';
  return { json: { ...p, groqPayload: { model: 'llama-3.3-70b-versatile', messages: [{ role: 'system', content: sysMsg }, { role: 'user', content: 'Generate the Arabic care message.' }], temperature: 0.5, max_tokens: 400 } } };
});

return $input.all().map((item, idx) => {
  const gr = item.json;
  const buildData = $('F — Build Groq Care Payload').all()[idx].json;
  let careText = '';
  try { careText = gr.choices[0].message.content || ''; } catch(e) {}
  if (!careText) careText = 'تذكر دائماً اتباع تعليمات طبيبك والراحة الكافية للتعافي السريع.';
  const intro = 'أهلاً ' + buildData.patient_name + '! 😊 نفتكرك بعد زيارتك مع ' + buildData.doctor_name + '. ';
  const outro = ' للأسئلة أو الحجز: ' + buildData.manager_phone + ' 💙';
  const fullMsg = intro + careText + outro;
  const safePhone = (buildData.patient_phone || '').replace(/'/g, "''");
  return { json: { ...buildData, careText, fullMsg, safePhone } };
});

const d = $json;
const payload = d.payload || d;
return [{ json: { command: payload.command || d.command || 'broadcast', custom_message: payload.custom_message || d.custom_message || 'رسالة من الإدارة', target_phone: payload.target_phone || d.target_phone || null, broadcast_message: payload.broadcast_message || d.broadcast_message || '', vip_phone: payload.vip_phone || null, missed_phone: payload.missed_phone || null, timestamp: new Date().toISOString() } }];
